import{_ as a,o as r,c as t,a2 as n}from"./chunks/framework.DNhnOc72.js";const m=JSON.parse('{"title":"Mi primer CTF: lo que aprendí","description":"Experiencia personal, tips para empezar y recursos recomendados","frontmatter":{"title":"Mi primer CTF: lo que aprendí","description":"Experiencia personal, tips para empezar y recursos recomendados"},"headers":[],"relativePath":"blog/05-mi-primer-ctf.md","filePath":"blog/05-mi-primer-ctf.md","lastUpdated":null}'),s={name:"blog/05-mi-primer-ctf.md"};function o(i,e,l,p,d,c){return r(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="mi-primer-ctf-lo-que-aprendi" tabindex="-1">Mi primer CTF: lo que aprendí <a class="header-anchor" href="#mi-primer-ctf-lo-que-aprendi" aria-label="Permalink to &quot;Mi primer CTF: lo que aprendí&quot;">​</a></h1><h2 id="¿que-es-un-ctf" tabindex="-1">¿Qué es un CTF? <a class="header-anchor" href="#¿que-es-un-ctf" aria-label="Permalink to &quot;¿Qué es un CTF?&quot;">​</a></h2><p><strong>CTF</strong> (Capture The Flag) es una competencia donde debes encontrar &quot;flags&quot; (texto oculto) resolviendo retos de ciberseguridad. Es la mejor forma de aprender practicando.</p><h2 id="mi-experiencia" tabindex="-1">Mi experiencia <a class="header-anchor" href="#mi-experiencia" aria-label="Permalink to &quot;Mi experiencia&quot;">​</a></h2><p>Cuando empecé en mi primer CTF, no sabía ni什么是 Nmap. Hoy puedo decirte que <strong>los CTFs cambiaron mi carrera</strong>.</p><h3 id="lo-que-encontre" tabindex="-1">Lo que encontré: <a class="header-anchor" href="#lo-que-encontre" aria-label="Permalink to &quot;Lo que encontré:&quot;">​</a></h3><ul><li><strong>Crypto</strong> — Descifrar mensajes con César, Vigenère, RSA</li><li><strong>Web</strong> — SQL injection, XSS, IDOR</li><li><strong>Forensics</strong> — Analizar imágenes de disco, pcaps</li><li><strong>Reverse Engineering</strong> — Desensamblar binarios</li><li><strong>Pwn</strong> — Explotar binaries con buffer overflow</li></ul><h3 id="lo-que-aprendi" tabindex="-1">Lo que aprendí: <a class="header-anchor" href="#lo-que-aprendi" aria-label="Permalink to &quot;Lo que aprendí:&quot;">​</a></h3><ol><li><strong>Google es tu mejor herramienta</strong> — Todos buscan soluciones</li><li><strong>Leer es clave</strong> — Los writesups son oro</li><li><strong>Practicar todos los días</strong> — Aunque sea 30 minutos</li><li><strong>No rendirse</strong> — El primer reto que resuelves es addictivo</li></ol><h2 id="tips-para-empezar" tabindex="-1">Tips para empezar <a class="header-anchor" href="#tips-para-empezar" aria-label="Permalink to &quot;Tips para empezar&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Elige una plataforma: TryHackMe (principiante) o HTB (intermedio)</span></span>
<span class="line"><span>2. Empieza por la ruta &quot;Beginner&quot;</span></span>
<span class="line"><span>3. Lee el writeup SIEMPRE después de resolver</span></span>
<span class="line"><span>4. Únete a un equipo (.twimg, Reddit)</span></span>
<span class="line"><span>5. Documenta todo en tu portafolio</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="recursos-gratuitos" tabindex="-1">Recursos gratuitos <a class="header-anchor" href="#recursos-gratuitos" aria-label="Permalink to &quot;Recursos gratuitos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Plataforma</th><th>Nivel</th><th>Precio</th></tr></thead><tbody><tr><td>TryHackMe</td><td>Principiante</td><td>Gratis / $10/mes</td></tr><tr><td>HackTheBox</td><td>Intermedio</td><td>Gratis / $14/mes</td></tr><tr><td>PicoCTF</td><td>Principiante</td><td>Gratis</td></tr><tr><td>OverTheWire</td><td>Intermedio</td><td>Gratis</td></tr><tr><td>CTFtime</td><td>Todos</td><td>Gratis</td></tr></tbody></table><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>Los CTFs no son solo competencias. Son <strong>entrenamiento real</strong> que te prepara para el mundo laboral. Cada reto que resuelves te hace mejor.</p><hr><p><em>Artículo publicado en el Blog CDPN — Semana 5</em></p>`,17)])])}const h=a(s,[["render",o]]);export{m as __pageData,h as default};
